import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import {
  Activity, ArrowDownLeft, ArrowUpRight, Bell, BookOpen, Check, ChevronDown, CircleDollarSign,
  ClipboardList, Copy, DoorOpen, Edit3, History, Home, LogOut, Plus, ReceiptText, Settings,
  ShieldCheck, Sparkles, Trash2, Users, Wallet, X, Utensils, CalendarDays, LockKeyhole, Mail,
  LoaderCircle, Coffee, Moon, Sun, Save, RefreshCw, UserRound, Search, CircleHelp
} from 'lucide-react';
